nter"><div class="card-body"><h5>QR Code Unit</h5><img class="img-fluid qr my-2" src="<?=e($qr)?>" alt="QR <?=e($b['kode'])?>"><p class="small text-secondary">QR ini mengarah ke identitas unit dan keterangannya.</p><a class="btn btn-outline-primary btn-sm" download="QR-<?=e($b['kode'])?>.png" href="<?=e($qr)?>">Unduh QR</a></div></div></div></div>
